// The embedded network, generated by cmake/embed_net.cmake. Empty when no
// network was embedded.
extern "C" {
extern const unsigned char gSuperpawnEmbeddedNet[];
extern const std::size_t   gSuperpawnEmbeddedNetSize;
}

namespace sp::nnue {

namespace {

std::uint64_t fnv1a(const std::uint8_t* data, std::size_t size) {
    std::uint64_t h = 0xCBF29CE484222325ULL;
    for (std::size_t i = 0; i < size; ++i)
        h = (h ^ data[i]) * 0x100000001B3ULL;
    return h;
}

std::uint32_t read_u32(const std::uint8_t* p) {
    return std::uint32_t(p[0]) | std::uint32_t(p[1]) << 8 | std::uint32_t(p[2]) << 16 | std::uint32_t(p[3]) << 24;
}

void write_u32(std::uint8_t* p, std::uint32_t v) {
    for (int i = 0; i < 4; ++i)
        p[i] = std::uint8_t(v >> (8 * i));
}

// Weights are stored little-endian; on a big-endian host byte-swap in place.
void to_host_order(std::int16_t* data, std::size_t count) {
    if constexpr (std::endian::native == std::endian::big)
        for (std::size_t i = 0; i < count; ++i)
            data[i] = std::int16_t(std::uint16_t(data[i]) << 8 | std::uint16_t(data[i]) >> 8);
    else
        (void)data, (void)count;
}

// ---------------------------------------------------------------------------
// SIMD primitives: add or subtract one weight row into an accumulator half,
// and the SCReLU dot product of the output layer.
// ---------------------------------------------------------------------------

inline void add_row(std::int16_t* acc, const std::int16_t* row) {
#if defined(SP_NNUE_AVX512)
    for (int i = 0; i < HIDDEN; i += 32) {
        auto a = _mm512_load_si512(reinterpret_cast<const __m512i*>(acc + i));
        auto w = _mm512_load_si512(reinterpret_cast<const __m512i*>(row + i));
        _mm512_store_si512(reinterpret_cast<__m512i*>(acc + i), _mm512_add_epi16(a, w));
    }
#elif defined(SP_NNUE_AVX2)
    for (int i = 0; i < HIDDEN; i += 16) {
        auto a = _mm256_load_si256(reinterpret_cast<const __m256i*>(acc + i));
        auto w = _mm256_load_si256(reinterpret_cast<const __m256i*>(row + i));
        _mm256_store_si256(reinterpret_cast<__m256i*>(acc + i), _mm256_add_epi16(a, w));
    }
#else
    for (int i = 0; i < HIDDEN; ++i)
        acc[i] = std::int16_t(acc[i] + row[i]);
#endif
}

inline void sub_row(std::int16_t* acc, const std::int16_t* row) {
#if defined(SP_NNUE_AVX512)
    for (int i = 0; i < HIDDEN; i += 32) {
        auto a = _mm512_load_si512(reinterpret_cast<const __m512i*>(acc + i));
        auto w = _mm512_load_si512(reinterpret_cast<const __m512i*>(row + i));
        _mm512_store_si512(reinterpret_cast<__m512i*>(acc + i), _mm512_sub_epi16(a, w));
    }
#elif defined(SP_NNUE_AVX2)
    for (int i = 0; i < HIDDEN; i += 16) {
        auto a = _mm256_load_si256(reinterpret_cast<const __m256i*>(acc + i));
        auto w = _mm256_load_si256(reinterpret_cast<const __m256i*>(row + i));
        _mm256_store_si256(reinterpret_cast<__m256i*>(acc + i), _mm256_sub_epi16(a, w));
    }
#else
    for (int i = 0; i < HIDDEN; ++i)
        acc[i] = std::int16_t(acc[i] - row[i]);
#endif
}

// sum over i of clamp(acc[i], 0, QA)^2 * w[i]. The product clamp * w is formed
// first and fits in 16 bits because |w| < 128; the second multiply by clamp
// widens to 32 bits. Each 32-bit lane sums HIDDEN / lanes products, which
// cannot overflow; the final horizontal sum is done in 64 bits.
inline std::int64_t screlu_dot(const std::int16_t* acc, const std::int16_t* w) {
#if defined(SP_NNUE_AVX512)
    const auto zero = _mm512_setzero_si512();
    const auto qa   = _mm512_set1_epi16(QA);
    auto       sum  = _mm512_setzero_si512();
    for (int i = 0; i < HIDDEN; i += 32) {
        auto a = _mm512_load_si512(reinterpret_cast<const __m512i*>(acc + i));
        auto v = _mm512_min_epi16(_mm512_max_epi16(a, zero), qa);
        auto p = _mm512_mullo_epi16(v, _mm512_load_si512(reinterpret_cast<const __m512i*>(w + i)));
        sum    = _mm512_add_epi32(sum, _mm512_madd_epi16(p, v));
    }
    alignas(64) std::int32_t lanes[16];
    _mm512_store_si512(reinterpret_cast<__m512i*>(lanes), sum);
    std::int64_t total = 0;
    for (int l : lanes)
        total += l;
    return total;
#elif defined(SP_NNUE_AVX2)
    const auto zero = _mm256_setzero_si256();
    const auto qa   = _mm256_set1_epi16(QA);
    auto       sum  = _mm256_setzero_si256();
    for (int i = 0; i < HIDDEN; i += 16) {
        auto a = _mm256_load_si256(reinterpret_cast<const __m256i*>(acc + i));
        auto v = _mm256_min_epi16(_mm256_max_epi16(a, zero), qa);
        auto p = _mm256_mullo_epi16(v, _mm256_load_si256(reinterpret_cast<const __m256i*>(w + i)));
        sum    = _mm256_add_epi32(sum, _mm256_madd_epi16(p, v));
    }
    alignas(32) std::int32_t lanes[8];
    _mm256_store_si256(reinterpret_cast<__m256i*>(lanes), sum);
    std::int64_t total = 0;
    for (int l : lanes)
        total += l;
    return total;
#else
    std::int64_t total = 0;
    for (int i = 0; i < HIDDEN; ++i) {
        const std::int32_t v = std::clamp<std::int32_t>(acc[i], 0, QA);
        total += std::int64_t(v * v) * w[i];
    }
    return total;
#endif
}

Value output(std::int64_t dot, std::int16_t bias) {
    // Undo one QA from the squared activation, add the bias (scaled by QA * QB
    // in the file), then convert to centipawns.
    return Value((dot / QA + bias) * SCALE / (QA * QB));
}

}  // namespace

const char* simd_name() {
#if defined(SP_NNUE_AVX512)
    return "AVX-512";
#elif defined(SP_NNUE_AVX2)
    return "AVX2";
#else
    return "scalar";
#endif
}

// ---------------------------------------------------------------------------
// Loading and saving
// ---------------------------------------------------------------------------

std::unique_ptr<Network> Network::from_bytes(const std::uint8_t* data, std::size_t size, std::string& error) {
    if (size != FILE_SIZE) {
        error = "wrong file size " + std::to_string(size) + ", expected " + std::to_string(FILE_SIZE)
              + " (network architecture " + std::to_string(INPUTS) + "x" + std::to_string(HIDDEN) + "x2 -> "
              + std::to_string(OUTPUT_BUCKETS) + ")";
        return nullptr;
    }

    if (std::memcmp(data, "SPNN", 4) != 0) {
        error = "not a Superpawn network file";
        return nullptr;
    }

    const std::uint32_t fields[8] = {FILE_VERSION, INPUTS, HIDDEN, OUTPUT_BUCKETS, QA, QB, SCALE, 0};
    const char*         names[8]  = {"version", "inputs", "hidden", "buckets", "qa", "qb", "scale", "reserved"};
    for (int i = 0; i < 8; ++i)
        if (read_u32(data + 4 + 4 * i) != fields[i]) {
            error = std::string("header field ") + names[i] + " is " + std::to_string(read_u32(data + 4 + 4 * i))
                  + ", expected " + std::to_string(fields[i]);
            return nullptr;
        }

    const std::uint8_t* weights = data + HEADER_SIZE;
    std::uint64_t       stored  = 0;
    for (int i = 0; i < 8; ++i)
        stored |= std::uint64_t(weights[WEIGHTS_SIZE + i]) << (8 * i);
    if (fnv1a(weights, WEIGHTS_SIZE) != stored) {
        error = "checksum mismatch";
        return nullptr;
    }

    auto net = std::make_unique<Network>();
    std::memcpy(net->featureWeights, weights, sizeof(net->featureWeights));
    weights += sizeof(net->featureWeights);
    std::memcpy(net->featureBias, weights, sizeof(net->featureBias));
    weights += sizeof(net->featureBias);
    std::memcpy(net->outputWeights, weights, sizeof(net->outputWeights));
    weights += sizeof(net->outputWeights);
    std::memcpy(net->outputBias, weights, sizeof(net->outputBias));

    to_host_order(net->featureWeights, INPUTS * HIDDEN);
    to_host_order(net->featureBias, HIDDEN);
    to_host_order(&net->outputWeights[0][0], OUTPUT_BUCKETS * 2 * HIDDEN);
    to_host_order(net->outputBias, OUTPUT_BUCKETS);

    for (const auto& bucket : net->outputWeights)
        for (std::int16_t w : bucket)
            if (w <= -128 || w >= 128) {
                error = "output weight " + std::to_string(w) + " out of the 16-bit safe range";
                return nullptr;
            }

    return net;
}

std::unique_ptr<Network> Network::load(const std::string& path, std::string& error) {
    std::ifstream file(path, std::ios::binary);
    if (!file) {
        error = "cannot open " + path;
        return nullptr;
    }

    std::vector<std::uint8_t> bytes((std::istreambuf_iterator<char>(file)), std::istreambuf_iterator<char>());
    auto                      net = from_bytes(bytes.data(), bytes.size(), error);
    if (net)
        net->name = path;
    return net;
}

std::unique_ptr<Network> Network::from_bullet(const std::string& path, std::string& error) {
    std::ifstream file(path, std::ios::binary);
    if (!file) {
        error = "cannot open " + path;
        return nullptr;
    }
    std::vector<std::uint8_t> bytes((std::istreambuf_iterator<char>(file)), std::istreambuf_iterator<char>());

    // bullet pads the file to a multiple of 64 bytes
    const std::size_t padded = (WEIGHTS_SIZE + 63) / 64 * 64;
    if (bytes.size() != WEIGHTS_SIZE && bytes.size() != padded) {
        error = "unexpected size " + std::to_string(bytes.size())
              + " for a bullet export of this architecture, expected " + std::to_string(WEIGHTS_SIZE) + " or "
              + std::to_string(padded);
        return nullptr;
    }

    auto                net = std::make_unique<Network>();
    const std::uint8_t* p   = bytes.data();
    std::memcpy(net->featureWeights, p, sizeof(net->featureWeights));
    p += sizeof(net->featureWeights);
    std::memcpy(net->featureBias, p, sizeof(net->featureBias));
    p += sizeof(net->featureBias);
    std::memcpy(net->outputWeights, p, sizeof(net->outputWeights));
    p += sizeof(net->outputWeights);
    std::memcpy(net->outputBias, p, sizeof(net->outputBias));

    to_host_order(net->featureWeights, INPUTS * HIDDEN);
    to_host_order(net->featureBias, HIDDEN);
    to_host_order(&net->outputWeights[0][0], OUTPUT_BUCKETS * 2 * HIDDEN);
    to_host_order(net->outputBias, OUTPUT_BUCKETS);

    for (const auto& bucket : net->outputWeights)
        for (std::int16_t w : bucket)
            if (w <= -128 || w >= 128) {
                error = "output weight " + std::to_string(w)
                      + " out of the 16-bit safe range; clip the trainer's output weights";
                return nullptr;
            }

    net->name = path;
    return net;
}

std::unique_ptr<Network> Network::load_embedded(std::string& error) {
    if (gSuperpawnEmbeddedNetSize == 0) {
        error = "no network embedded in this build";
        return nullptr;
    }
    auto net = from_bytes(gSuperpawnEmbeddedNet, gSuperpawnEmbeddedNetSize, error);
    if (net)
        net->name = "<embedded>";
    return net;
}

bool Network::save(const std::string& path) const {
    std::vector<std::uint8_t> bytes(FILE_SIZE);
    std::memcpy(bytes.data(), "SPNN", 4);
    const std::uint32_t fields[8] = {FILE_VERSION, INPUTS, HIDDEN, OUTPUT_BUCKETS, QA, QB, SCALE, 0};
    for (int i = 0; i < 8; ++i)
        write_u32(bytes.data() + 4 + 4 * i, fields[i]);

    std::uint8_t* p   = bytes.data() + HEADER_SIZE;
    auto          put = [&](const std::int16_t* data, std::size_t count) {
        for (std::size_t i = 0; i < count; ++i) {
            *p++ = std::uint8_t(std::uint16_t(data[i]));
            *p++ = std::uint8_t(std::uint16_t(data[i]) >> 8);
        }
    };
    put(featureWeights, INPUTS * HIDDEN);
    put(featureBias, HIDDEN);
    put(&outputWeights[0][0], OUTPUT_BUCKETS * 2 * HIDDEN);
    put(outputBias, OUTPUT_BUCKETS);

    const std::uint64_t checksum = fnv1a(bytes.data() + HEADER_SIZE, WEIGHTS_SIZE);
    for (int i = 0; i < 8; ++i)
        *p++ = std::uint8_t(checksum >> (8 * i));

    std::ofstream file(path, std::ios::binary);
    file.write(reinterpret_cast<const char*>(bytes.data()), std::streamsize(bytes.size()));
    return bool(file);
}

// ---------------------------------------------------------------------------
// Accumulators
// ---------------------------------------------------------------------------

void refresh(const Network& net, const Position& pos, Accumulator& acc) {
    for (Color c : {WHITE, BLACK}) {
        std::memcpy(acc.v[c], net.featureBias, sizeof(acc.v[c]));
        for (Bitboard b = pos.pieces(); b;) {
            const Square s = pop_lsb(b);
            add_row(acc.v[c], &net.featureWeights[feature_index(c, pos.piece_on(s), s) * HIDDEN]);
        }
    }
    acc.computed = true;
}

void update(const Network& net, const Accumulator& prev, Accumulator& acc, const DirtyPiece& dp) {
    for (Color c : {WHITE, BLACK}) {
        std::memcpy(acc.v[c], prev.v[c], sizeof(acc.v[c]));
        for (int i = 0; i < dp.count; ++i) {
            if (dp.from[i] != SQ_NONE)
                sub_row(acc.v[c], &net.featureWeights[feature_index(c, dp.piece[i], dp.from[i]) * HIDDEN]);
            if (dp.to[i] != SQ_NONE)
                add_row(acc.v[c], &net.featureWeights[feature_index(c, dp.piece[i], dp.to[i]) * HIDDEN]);
        }
    }
    acc.computed = true;
}

// Walks back from the current ply to the nearest computed accumulator and
// brings everything in between up to date. Without any computed ancestor the
// current accumulator is refreshed from the board; this happens once per
// search for each thread, since every later node has a computed parent.
const Accumulator& accumulator(const Network& net, const Position& pos) {
    auto&       stack = pos.accumulators();
    std::size_t top   = stack.size() - 1;

    if (stack[top].computed)
        return stack[top];

    std::size_t from = top;
    while (from > 0 && !stack[from - 1].computed)
        --from;

    if (from == 0 && !stack[0].computed) {
        refresh(net, pos, stack[top]);
        return stack[top];
    }

    for (std::size_t i = from; i <= top; ++i)
        update(net, stack[i - 1], stack[i], pos.dirty_piece(i));

    return stack[top];
}

Value evaluate_scalar(const Network& net, const Accumulator& acc, Color stm, int bucket) {
    std::int64_t dot = 0;
    for (int i = 0; i < HIDDEN; ++i) {
        const std::int32_t us   = std::clamp<std::int32_t>(acc.v[stm][i], 0, QA);
        const std::int32_t them = std::clamp<std::int32_t>(acc.v[~stm][i], 0, QA);
        dot += std::int64_t(us * us) * net.outputWeights[bucket][i];
        dot += std::int64_t(them * them) * net.outputWeights[bucket][HIDDEN + i];
    }
    return output(dot, net.outputBias[bucket]);
}

Value evaluate(const Network& net, const Position& pos) {
    const Accumulator& acc    = accumulator(net, pos);
    const Color        stm    = pos.side_to_move();
    const int          bucket = output_bucket(popcount(pos.pieces()));

    const std::int64_t dot =
        screlu_dot(acc.v[stm], net.outputWeights[bucket]) + screlu_dot(acc.v[~stm], net.outputWeights[bucket] + HIDDEN);

    return output(dot, net.outputBias[bucket]);
}

}  // namespace sp::nnue
